import { TriviaQuestion } from '../trivia-types'

export const ART_QUESTIONS: TriviaQuestion[] = [
  { id: 'art-1', category: 'art', difficulty: 'easy', question: 'Who painted the Mona Lisa?', answer: 'Leonardo da Vinci', options: ['Michelangelo', 'Leonardo da Vinci', 'Raphael', 'Botticelli'], explanation: 'Leonardo da Vinci painted the Mona Lisa between approximately 1503 and 1519. The painting hangs in the Louvre Museum in Paris behind bulletproof glass and is believed to depict Lisa Gherardini, wife of a Florentine merchant.' },
  { id: 'art-2', category: 'art', difficulty: 'easy', question: 'What art movement is Claude Monet associated with?', answer: 'Impressionism', options: ['Cubism', 'Impressionism', 'Romanticism', 'Surrealism'], explanation: 'Monet is considered the founder of Impressionism, a movement that emphasized capturing light and atmosphere over precise detail. The movement got its name from his 1872 painting "Impression, Sunrise."' },
  { id: 'art-3', category: 'art', difficulty: 'easy', question: 'Who sculpted the statue of David?', answer: 'Michelangelo', options: ['Donatello', 'Bernini', 'Michelangelo', 'Rodin'], explanation: 'Michelangelo carved David from a single block of marble between 1501 and 1504. The 17-foot statue stands in the Galleria dell\'Accademia in Florence and depicts the biblical hero before his battle with Goliath.' },
  { id: 'art-4', category: 'art', difficulty: 'easy', question: 'What famous painting shows a starry night sky swirling over a village?', answer: 'The Starry Night', options: ['Starry Night Over the Rhone', 'The Starry Night', 'Moonlight', 'Night Sky'], explanation: 'Vincent van Gogh painted The Starry Night in June 1889 while staying at the Saint-Paul-de-Mausole asylum in southern France. The painting now hangs in the Museum of Modern Art (MoMA) in New York City.' },
  { id: 'art-5', category: 'art', difficulty: 'easy', question: 'What museum houses the Mona Lisa?', answer: 'The Louvre', options: ['The Uffizi', 'The Louvre', 'The Met', 'The Prado'], explanation: 'The Louvre in Paris is the world\'s most-visited art museum, with about 10 million visitors per year. The museum is housed in a former royal palace and its collection spans over 9,000 years of history.' },
  { id: 'art-6', category: 'art', difficulty: 'easy', question: 'Who painted the ceiling of the Sistine Chapel?', answer: 'Michelangelo', options: ['Leonardo da Vinci', 'Raphael', 'Michelangelo', 'Caravaggio'], explanation: 'Michelangelo painted the Sistine Chapel ceiling between 1508 and 1512, commissioned by Pope Julius II. The ceiling contains over 300 figures and covers about 5,000 square feet, with "The Creation of Adam" being its most famous panel.' },
  { id: 'art-7', category: 'art', difficulty: 'easy', question: 'What does the term "Renaissance" mean?', answer: 'Rebirth', options: ['Revolution', 'Rebirth', 'Restoration', 'Renewal'], explanation: 'The Renaissance, meaning "rebirth" in French, was a cultural movement spanning roughly the 14th to 17th centuries. It began in Italy and marked a renewed interest in classical Greek and Roman art, philosophy, and learning.' },
  { id: 'art-8', category: 'art', difficulty: 'easy', question: 'Who is famous for painting Campbell\'s Soup Cans?', answer: 'Andy Warhol', options: ['Roy Lichtenstein', 'Andy Warhol', 'Jasper Johns', 'Keith Haring'], explanation: 'Andy Warhol created his Campbell\'s Soup Cans series in 1962, consisting of 32 canvases (one for each flavor). The work became an icon of the Pop Art movement and challenged traditional ideas about what constitutes art.' },
  { id: 'art-9', category: 'art', difficulty: 'easy', question: 'What art movement featured melting clocks and dreamlike imagery?', answer: 'Surrealism', options: ['Dadaism', 'Surrealism', 'Abstract Expressionism', 'Futurism'], explanation: 'Surrealism sought to unlock the creative potential of the unconscious mind, inspired by Sigmund Freud\'s theories. Salvador Dali\'s "The Persistence of Memory" (1931) with its melting clocks is the movement\'s most recognizable image.' },
  { id: 'art-10', category: 'art', difficulty: 'easy', question: 'Who cut off part of his own ear?', answer: 'Vincent van Gogh', options: ['Paul Gauguin', 'Vincent van Gogh', 'Edvard Munch', 'Henri Matisse'], explanation: 'Van Gogh severed part of his left ear in December 1888 during a mental health crisis in Arles, France. He reportedly delivered the severed piece to a woman at a local establishment. He continued painting prolifically until his death in 1890.' },
  { id: 'art-11', category: 'art', difficulty: 'easy', question: 'What famous sculpture depicts a person sitting with chin resting on hand, deep in thought?', answer: 'The Thinker', options: ['The Kiss', 'The Thinker', 'The Burghers of Calais', 'David'], explanation: 'Auguste Rodin created The Thinker in 1904, originally designed as part of a larger work called The Gates of Hell. The figure was initially meant to represent the poet Dante contemplating his epic poem.' },
  { id: 'art-12', category: 'art', difficulty: 'easy', question: 'What three primary colors are used in painting?', answer: 'Red, blue, and yellow', options: ['Red, green, and blue', 'Red, blue, and yellow', 'Cyan, magenta, and yellow', 'Red, orange, and blue'], explanation: 'In traditional color theory for painting, red, blue, and yellow are the three primary colors that cannot be created by mixing other colors. Note that digital screens use red, green, and blue (RGB), and printers use cyan, magenta, yellow, and black (CMYK).' },
  { id: 'art-13', category: 'art', difficulty: 'easy', question: 'Who painted "The Birth of Venus"?', answer: 'Sandro Botticelli', options: ['Leonardo da Vinci', 'Sandro Botticelli', 'Titian', 'Raphael'], explanation: 'Botticelli painted The Birth of Venus around 1485, depicting the goddess Venus emerging from the sea as a fully grown woman. The painting hangs in the Uffizi Gallery in Florence and is one of the most famous works of the Italian Renaissance.' },
  { id: 'art-14', category: 'art', difficulty: 'easy', question: 'What is a fresco?', answer: 'A painting done on wet plaster', options: ['A painting on canvas', 'A painting done on wet plaster', 'A type of sculpture', 'A watercolor technique'], explanation: 'Fresco painting involves applying pigment to freshly laid wet plaster, which absorbs the color as it dries. This technique was used extensively in the Renaissance, most famously by Michelangelo on the Sistine Chapel ceiling.' },
  { id: 'art-15', category: 'art', difficulty: 'easy', question: 'What painting by Edvard Munch shows a figure with an agonized expression on a bridge?', answer: 'The Scream', options: ['The Scream', 'Anxiety', 'Despair', 'The Storm'], explanation: 'Edvard Munch created The Scream in 1893, and it became one of the most iconic images in art history. Munch actually created four versions of the composition — two paintings and two pastels.' },
  { id: 'art-16', category: 'art', difficulty: 'easy', question: 'What nationality was Pablo Picasso?', answer: 'Spanish', options: ['French', 'Italian', 'Spanish', 'Portuguese'], explanation: 'Picasso was born in Malaga, Spain in 1881, though he spent most of his adult life in France. He is estimated to have produced about 50,000 artworks during his lifetime, including paintings, drawings, sculptures, and ceramics.' },
  { id: 'art-17', category: 'art', difficulty: 'easy', question: 'What is the term for a painting of a person\'s face or figure?', answer: 'Portrait', options: ['Still life', 'Landscape', 'Portrait', 'Abstract'], explanation: 'Portrait painting has been one of the most enduring genres in art, dating back to ancient Egypt and Rome. Before photography, painted portraits were the primary way to record a person\'s appearance for posterity.' },
  { id: 'art-18', category: 'art', difficulty: 'easy', question: 'Who is known for painting water lilies?', answer: 'Claude Monet', options: ['Pierre-Auguste Renoir', 'Claude Monet', 'Edgar Degas', 'Camille Pissarro'], explanation: 'Monet painted approximately 250 water lily paintings over the last 30 years of his life, inspired by the garden he created at his home in Giverny, France. The large-scale Water Lilies murals at the Musee de l\'Orangerie in Paris are among his most celebrated works.' },
  { id: 'art-19', category: 'art', difficulty: 'easy', question: 'What famous painting shows George Washington crossing the Delaware River?', answer: 'Washington Crossing the Delaware', options: ['Washington Crossing the Delaware', 'The Spirit of \'76', 'Declaration of Independence', 'Battle of Bunker Hill'], explanation: 'Emanuel Leutze painted Washington Crossing the Delaware in 1851, depicting the surprise attack on Christmas night, 1776. The painting is historically inaccurate in several details — the flag shown didn\'t exist yet, and the boat type is wrong.' },
  { id: 'art-20', category: 'art', difficulty: 'easy', question: 'What is an art gallery that is part of a larger museum called?', answer: 'A wing', options: ['A hall', 'A wing', 'A vault', 'A salon'], explanation: 'Museum wings are named sections that often house specific collections or periods of art. Famous examples include the Denon Wing of the Louvre (which houses the Mona Lisa) and the American Wing of the Metropolitan Museum of Art.' },
  { id: 'art-21', category: 'art', difficulty: 'easy', question: 'What Mexican artist is known for her self-portraits and unibrow?', answer: 'Frida Kahlo', options: ['Frida Kahlo', 'Diego Rivera', 'Remedios Varo', 'Leonora Carrington'], explanation: 'Frida Kahlo created 55 self-portraits out of her 143 total paintings, often depicting her physical and emotional pain. She suffered a devastating bus accident at age 18 that left her with lifelong injuries and began painting during her recovery.' },
  { id: 'art-22', category: 'art', difficulty: 'easy', question: 'What art technique uses small dots of color to form an image?', answer: 'Pointillism', options: ['Stippling', 'Pointillism', 'Hatching', 'Sgraffito'], explanation: 'Pointillism was developed by Georges Seurat and Paul Signac in the 1880s. Seurat\'s masterpiece "A Sunday Afternoon on the Island of La Grande Jatte" (1886) is the most famous example, composed entirely of tiny dots of pure color.' },
  { id: 'art-23', category: 'art', difficulty: 'easy', question: 'What ancient civilization is known for building the Great Sphinx?', answer: 'Ancient Egypt', options: ['Ancient Greece', 'Ancient Egypt', 'Ancient Rome', 'Mesopotamia'], explanation: 'The Great Sphinx of Giza was carved from limestone bedrock around 2500 BC, likely during the reign of Pharaoh Khafre. It has the body of a lion and the head of a human, standing 20 meters tall and 73 meters long.' },
  { id: 'art-24', category: 'art', difficulty: 'easy', question: 'What is the art of beautiful handwriting called?', answer: 'Calligraphy', options: ['Typography', 'Calligraphy', 'Lettering', 'Cursive'], explanation: 'Calligraphy comes from the Greek words for "beautiful writing." It has been practiced across cultures for thousands of years, from Chinese and Japanese brush calligraphy to Islamic geometric calligraphy to Western scripts.' },
  { id: 'art-25', category: 'art', difficulty: 'easy', question: 'What color do you get when you mix blue and yellow paint?', answer: 'Green', options: ['Purple', 'Green', 'Orange', 'Brown'], explanation: 'Blue and yellow are two of the three primary colors in traditional color theory. When mixed, they create green, which is a secondary color. The shade of green depends on the proportions and specific pigments used.' },
  { id: 'art-26', category: 'art', difficulty: 'easy', question: 'What famous New York museum is known by the abbreviation MoMA?', answer: 'Museum of Modern Art', options: ['Metropolitan Museum of Art', 'Museum of Modern Art', 'Museum of Moving Arts', 'Museum of Media Arts'], explanation: 'MoMA opened in 1929 and houses one of the world\'s finest collections of modern and contemporary art. Its collection includes Van Gogh\'s Starry Night, Picasso\'s Les Demoiselles d\'Avignon, and Warhol\'s Campbell\'s Soup Cans.' },
  { id: 'art-27', category: 'art', difficulty: 'easy', question: 'Who painted "Girl with a Pearl Earring"?', answer: 'Johannes Vermeer', options: ['Rembrandt', 'Johannes Vermeer', 'Frans Hals', 'Jan Steen'], explanation: 'Vermeer painted Girl with a Pearl Earring around 1665, and it is sometimes called the "Mona Lisa of the North." The painting hangs in the Mauritshuis museum in The Hague, Netherlands, and the identity of the girl remains unknown.' },
  { id: 'art-28', category: 'art', difficulty: 'easy', question: 'What type of paint dries very quickly and is made with an acrylic polymer?', answer: 'Acrylic paint', options: ['Oil paint', 'Acrylic paint', 'Watercolor', 'Tempera'], explanation: 'Acrylic paint was developed in the 1940s and became widely available in the 1960s. Unlike oil paint, which can take days or weeks to dry, acrylic dries within minutes and is water-soluble when wet but waterproof when dry.' },
  { id: 'art-29', category: 'art', difficulty: 'easy', question: 'What is the name of the large bronze statue in New York Harbor?', answer: 'Statue of Liberty', options: ['Statue of Liberty', 'Colossus of Rhodes', 'Lady Freedom', 'Columbia'], explanation: 'The Statue of Liberty was a gift from France to the United States, dedicated in 1886. Designed by sculptor Frederic Auguste Bartholdi with an iron framework by Gustave Eiffel, it stands about 93 meters tall including its pedestal.' },
  { id: 'art-30', category: 'art', difficulty: 'easy', question: 'What art movement of the 1960s used images from popular culture and mass media?', answer: 'Pop Art', options: ['Op Art', 'Pop Art', 'Minimalism', 'Conceptual Art'], explanation: 'Pop Art emerged in the late 1950s and 1960s, drawing from advertising, comic books, and consumer products. Key artists include Andy Warhol, Roy Lichtenstein, and Jasper Johns.' },
  { id: 'art-31', category: 'art', difficulty: 'easy', question: 'What is a self-portrait?', answer: 'An artwork of the artist by the artist', options: ['A photograph taken by oneself', 'An artwork of the artist by the artist', 'A portrait commissioned by the subject', 'A mirror image painting'], explanation: 'Self-portraits have been created throughout art history, with Rembrandt being one of the most prolific, painting about 80 self-portraits. The tradition allows artists to practice portraiture and explore their own identity and aging.' },
  { id: 'art-32', category: 'art', difficulty: 'easy', question: 'What Italian city was the birthplace of the Renaissance?', answer: 'Florence', options: ['Rome', 'Venice', 'Florence', 'Milan'], explanation: 'Florence (Firenze) was the cradle of the Renaissance, largely due to the patronage of the wealthy Medici family. The city produced or nurtured artists like Leonardo da Vinci, Michelangelo, Botticelli, and Brunelleschi.' },
  { id: 'art-33', category: 'art', difficulty: 'easy', question: 'Who painted "American Gothic," showing a farmer and woman in front of a house?', answer: 'Grant Wood', options: ['Norman Rockwell', 'Edward Hopper', 'Grant Wood', 'Andrew Wyeth'], explanation: 'Grant Wood painted American Gothic in 1930, using his sister and his dentist as models. The painting depicts figures standing before a house with a distinctive Gothic window in Eldon, Iowa, which still stands today.' },
  { id: 'art-34', category: 'art', difficulty: 'easy', question: 'What is a mosaic?', answer: 'An image made from small pieces of stone, tile, or glass', options: ['A type of wall painting', 'An image made from small pieces of stone, tile, or glass', 'A carved relief sculpture', 'A type of stained glass'], explanation: 'Mosaics have been used since ancient Mesopotamia, Greece, and Rome to decorate floors, walls, and ceilings. The technique involves arranging small colored pieces called tesserae into patterns or images, often set in mortar.' },
  { id: 'art-35', category: 'art', difficulty: 'easy', question: 'What painting by Leonardo da Vinci depicts Jesus and his disciples at their final meal?', answer: 'The Last Supper', options: ['The Last Supper', 'The Wedding at Cana', 'The Supper at Emmaus', 'The Feast of the Gods'], explanation: 'Leonardo painted The Last Supper on the wall of the Santa Maria delle Grazie convent in Milan between 1495 and 1498. Unlike a true fresco, Leonardo used an experimental technique on dry plaster, which has caused significant deterioration over the centuries.' },
  { id: 'art-36', category: 'art', difficulty: 'medium', question: 'What art movement did Pablo Picasso and Georges Braque co-found?', answer: 'Cubism', options: ['Fauvism', 'Cubism', 'Futurism', 'Constructivism'], explanation: 'Picasso and Braque developed Cubism between 1907 and 1914, breaking objects into geometric forms shown from multiple viewpoints simultaneously. Picasso\'s "Les Demoiselles d\'Avignon" (1907) is often considered the first Cubist painting.' },
  { id: 'art-37', category: 'art', difficulty: 'medium', question: 'What painting was stolen from the Louvre in 1911 and missing for two years?', answer: 'Mona Lisa', options: ['Mona Lisa', 'Liberty Leading the People', 'The Wedding at Cana', 'Winged Victory of Samothrace'], explanation: 'Vincenzo Peruggia, an Italian handyman who had worked at the Louvre, hid inside the museum and walked out with the Mona Lisa under his coat. The theft made the painting world-famous, and it was recovered in 1913 when Peruggia tried to sell it to a gallery in Florence.' },
  { id: 'art-38', category: 'art', difficulty: 'medium', question: 'What architect designed the Guggenheim Museum in New York?', answer: 'Frank Lloyd Wright', options: ['Frank Gehry', 'Frank Lloyd Wright', 'I.M. Pei', 'Le Corbusier'], explanation: 'Frank Lloyd Wright designed the Solomon R. Guggenheim Museum, which opened in 1959. Its distinctive spiral ramp design allows visitors to view art while walking continuously upward. It was one of Wright\'s last major works before his death in 1959.' },
  { id: 'art-39', category: 'art', difficulty: 'medium', question: 'What technique involves scratching through a surface layer to reveal a different color beneath?', answer: 'Sgraffito', options: ['Impasto', 'Sgraffito', 'Glazing', 'Grisaille'], explanation: 'Sgraffito comes from the Italian word "sgraffiare" meaning "to scratch." It has been used in pottery, wall decoration, and painting for centuries. The technique was especially popular in Renaissance-era European building facades.' },
  { id: 'art-40', category: 'art', difficulty: 'medium', question: 'Who painted "Guernica"?', answer: 'Pablo Picasso', options: ['Salvador Dali', 'Pablo Picasso', 'Joan Miro', 'Diego Rivera'], explanation: 'Picasso painted Guernica in 1937 in response to the bombing of the Basque town of Guernica during the Spanish Civil War. The massive black-and-white painting (3.5 by 7.8 meters) now hangs in the Museo Reina Sofia in Madrid.' },
  { id: 'art-41', category: 'art', difficulty: 'medium', question: 'What is chiaroscuro?', answer: 'The use of strong contrasts between light and dark', options: ['A type of Italian sculpture', 'The use of strong contrasts between light and dark', 'A painting technique using only earth tones', 'A style of religious iconography'], explanation: 'Chiaroscuro is an Italian term meaning "light-dark" and was mastered by artists like Caravaggio and Rembrandt. The technique creates dramatic three-dimensional effects by using extreme contrast between illuminated areas and deep shadows.' },
  { id: 'art-42', category: 'art', difficulty: 'medium', question: 'What street artist is known for politically charged stencil works and a shredded painting at auction?', answer: 'Banksy', options: ['Shepard Fairey', 'Banksy', 'Jean-Michel Basquiat', 'KAWS'], explanation: 'Banksy\'s true identity remains unknown. In 2018, his painting "Girl with Balloon" partially self-destructed through a shredder hidden in its frame moments after selling at Sotheby\'s for 1.04 million pounds. The shredded version later sold for 18.6 million pounds in 2021.' },
  { id: 'art-43', category: 'art', difficulty: 'medium', question: 'What is the term for Japanese woodblock printing?', answer: 'Ukiyo-e', options: ['Sumi-e', 'Ukiyo-e', 'Kintsugi', 'Wabi-sabi'], explanation: 'Ukiyo-e means "pictures of the floating world" and flourished from the 17th to 19th centuries. Hokusai\'s "The Great Wave off Kanagawa" is the most famous ukiyo-e print, and the style heavily influenced the French Impressionists.' },
  { id: 'art-44', category: 'art', difficulty: 'medium', question: 'Who painted "Nighthawks," depicting people in a late-night diner?', answer: 'Edward Hopper', options: ['Norman Rockwell', 'Edward Hopper', 'Grant Wood', 'Andrew Wyeth'], explanation: 'Edward Hopper painted Nighthawks in 1942, capturing a sense of urban loneliness and isolation. The painting was inspired by a diner in Greenwich Village, Manhattan, and now hangs at the Art Institute of Chicago.' },
  { id: 'art-45', category: 'art', difficulty: 'medium', question: 'What 19th-century art movement was a reaction against industrialization, emphasizing nature and emotion?', answer: 'Romanticism', options: ['Realism', 'Romanticism', 'Naturalism', 'Pre-Raphaelitism'], explanation: 'Romanticism flourished from the late 18th to mid-19th century, valuing emotion, individualism, and the sublime power of nature. Key artists include Caspar David Friedrich, J.M.W. Turner, and Eugene Delacroix.' },
  { id: 'art-46', category: 'art', difficulty: 'medium', question: 'What is the name of the glass pyramid entrance to the Louvre?', answer: 'Louvre Pyramid', options: ['Crystal Palace', 'Louvre Pyramid', 'Pyramide Inversee', 'Grand Pyramid'], explanation: 'The Louvre Pyramid was designed by Chinese-American architect I.M. Pei and completed in 1989. Made of glass and metal, it stands 21.6 meters tall and was initially controversial but is now considered an iconic Parisian landmark.' },
  { id: 'art-47', category: 'art', difficulty: 'medium', question: 'What art movement sought to depict the speed and dynamism of modern life?', answer: 'Futurism', options: ['Futurism', 'Constructivism', 'De Stijl', 'Art Nouveau'], explanation: 'Futurism was founded in Italy in 1909 by Filippo Tommaso Marinetti, who published its manifesto in a French newspaper. The movement glorified technology, speed, and machinery, and influenced later movements like Art Deco and Constructivism.' },
  { id: 'art-48', category: 'art', difficulty: 'medium', question: 'Who created the sculpture "The Kiss"?', answer: 'Auguste Rodin', options: ['Auguste Rodin', 'Antonio Canova', 'Constantin Brancusi', 'Alberto Giacometti'], explanation: 'Rodin created The Kiss in 1882, originally as part of his Gates of Hell commission. The marble sculpture depicts the 13th-century lovers Paolo and Francesca from Dante\'s Inferno, and copies exist in museums around the world.' },
  { id: 'art-49', category: 'art', difficulty: 'medium', question: 'What medium does an artist use in a lithograph?', answer: 'Stone or metal plate with greasy crayon or ink', options: ['Carved wood block', 'Stone or metal plate with greasy crayon or ink', 'Etched copper plate with acid', 'Silk screen with stencil'], explanation: 'Lithography was invented in 1796 by Alois Senefelder. The process relies on the principle that oil and water do not mix — the artist draws on stone with a greasy medium, and ink adheres only to the drawn areas.' },
  { id: 'art-50', category: 'art', difficulty: 'medium', question: 'What Dutch Golden Age painter is famous for his use of light and self-portraits?', answer: 'Rembrandt', options: ['Vermeer', 'Rembrandt', 'Frans Hals', 'Jan van Eyck'], explanation: 'Rembrandt van Rijn (1606-1669) painted about 80 self-portraits over his career, documenting his own aging with unflinching honesty. He is considered one of the greatest painters in European art history, known for his masterful use of light and shadow.' },
  { id: 'art-51', category: 'art', difficulty: 'medium', question: 'What is "en plein air" painting?', answer: 'Painting outdoors', options: ['Painting with an airbrush', 'Painting outdoors', 'Painting on wet plaster', 'Painting with palette knife'], explanation: 'En plein air is French for "in the open air" and was central to the Impressionist movement. The development of portable paint tubes in the 1840s made outdoor painting much more practical, liberating artists from the studio.' },
  { id: 'art-52', category: 'art', difficulty: 'medium', question: 'Who designed the dome of the Florence Cathedral (Il Duomo)?', answer: 'Filippo Brunelleschi', options: ['Leon Battista Alberti', 'Filippo Brunelleschi', 'Bramante', 'Michelangelo'], explanation: 'Brunelleschi engineered the dome between 1420 and 1436 without traditional scaffolding, using an innovative double-shell design. It remains the largest brick dome ever constructed, spanning 45 meters, and his construction methods were so advanced they are still studied today.' },
  { id: 'art-53', category: 'art', difficulty: 'medium', question: 'What art movement featured geometric shapes and primary colors, founded by Piet Mondrian?', answer: 'De Stijl', options: ['Bauhaus', 'De Stijl', 'Suprematism', 'Minimalism'], explanation: 'De Stijl (Dutch for "The Style") was founded in 1917 in the Netherlands. Mondrian\'s paintings of black grid lines filled with primary colors (red, blue, yellow) and white became the movement\'s most recognizable works.' },
  { id: 'art-54', category: 'art', difficulty: 'medium', question: 'What painting sold for $450.3 million in 2017, making it the most expensive painting ever sold at auction?', answer: 'Salvator Mundi', options: ['Interchange', 'Salvator Mundi', 'Les Femmes d\'Alger', 'Shot Sage Blue Marilyn'], explanation: 'Salvator Mundi, attributed to Leonardo da Vinci, was sold at Christie\'s in November 2017 to Saudi Crown Prince Mohammed bin Salman. The painting depicts Christ holding a crystal orb and its attribution to Leonardo remains debated among scholars.' },
  { id: 'art-55', category: 'art', difficulty: 'medium', question: 'What Impressionist artist is best known for paintings of ballet dancers?', answer: 'Edgar Degas', options: ['Claude Monet', 'Edgar Degas', 'Pierre-Auguste Renoir', 'Mary Cassatt'], explanation: 'About half of Degas\'s works depict dancers, earning him the reputation as the "painter of dancers." He often painted backstage scenes and rehearsals rather than performances, capturing the hard work behind the graceful art form.' },
  { id: 'art-56', category: 'art', difficulty: 'medium', question: 'What is trompe l\'oeil?', answer: 'A visual illusion that makes flat art appear three-dimensional', options: ['A type of French sculpture', 'A visual illusion that makes flat art appear three-dimensional', 'A technique for painting on curved surfaces', 'A method of color mixing'], explanation: 'Trompe l\'oeil is French for "deceive the eye" and has been used since ancient times. Roman murals at Pompeii used the technique to create false windows and architectural details, and it remains popular in modern street art and murals.' },
  { id: 'art-57', category: 'art', difficulty: 'medium', question: 'Who painted "A Sunday Afternoon on the Island of La Grande Jatte"?', answer: 'Georges Seurat', options: ['Claude Monet', 'Georges Seurat', 'Paul Cezanne', 'Camille Pissarro'], explanation: 'Seurat spent two years (1884-1886) creating this masterpiece using his pointillist technique. The painting depicts Parisians relaxing in a park on an island in the Seine and is now housed at the Art Institute of Chicago.' },
  { id: 'art-58', category: 'art', difficulty: 'medium', question: 'What photographer is known for her portraits during the Great Depression, including "Migrant Mother"?', answer: 'Dorothea Lange', options: ['Ansel Adams', 'Dorothea Lange', 'Margaret Bourke-White', 'Walker Evans'], explanation: 'Dorothea Lange took "Migrant Mother" in 1936, showing Florence Owens Thompson with her children in a pea pickers\' camp. The photo became one of the most iconic images of the Great Depression and helped bring public attention to the plight of migrant workers.' },
  { id: 'art-59', category: 'art', difficulty: 'medium', question: 'What art movement used wild, bold colors and was led by Henri Matisse?', answer: 'Fauvism', options: ['Expressionism', 'Fauvism', 'Post-Impressionism', 'Symbolism'], explanation: 'Fauvism got its name from the French word "fauves" meaning "wild beasts," a term critics used mockingly at the 1905 Salon d\'Automne in Paris. Matisse and Andre Derain led the movement, using vivid, non-naturalistic colors.' },
  { id: 'art-60', category: 'art', difficulty: 'medium', question: 'What is impasto?', answer: 'Thick application of paint creating visible texture', options: ['Thin transparent layers of paint', 'Thick application of paint creating visible texture', 'A wash of diluted watercolor', 'Painting with a sponge'], explanation: 'Impasto involves applying paint so thickly that brush or palette knife strokes are clearly visible. Vincent van Gogh was a master of the technique, using heavy impasto to create the swirling textures in works like The Starry Night.' },
  { id: 'art-61', category: 'art', difficulty: 'medium', question: 'What is the largest art museum in the world by gallery space?', answer: 'The Louvre', options: ['The Met', 'The Hermitage', 'The Louvre', 'The Vatican Museums'], explanation: 'The Louvre has approximately 72,735 square meters of gallery space housing over 380,000 objects, of which about 35,000 are on display. The museum occupies the Louvre Palace, which was originally built as a fortress in the 12th century.' },
  { id: 'art-62', category: 'art', difficulty: 'medium', question: 'Who created the bronze doors known as the "Gates of Paradise" for the Florence Baptistery?', answer: 'Lorenzo Ghiberti', options: ['Donatello', 'Lorenzo Ghiberti', 'Andrea Pisano', 'Filippo Brunelleschi'], explanation: 'Ghiberti worked on the east doors of the Florence Baptistery from 1425 to 1452. Michelangelo supposedly called them the "Gates of Paradise" because of their extraordinary beauty. The ten gilded bronze panels depict scenes from the Old Testament.' },
  { id: 'art-63', category: 'art', difficulty: 'medium', question: 'What American artist is known for paintings of large flowers and New Mexico landscapes?', answer: 'Georgia O\'Keeffe', options: ['Georgia O\'Keeffe', 'Mary Cassatt', 'Helen Frankenthaler', 'Agnes Martin'], explanation: 'Georgia O\'Keeffe (1887-1986) is known as the "Mother of American Modernism." Her close-up paintings of flowers, such as "Jimson Weed/White Flower No. 1," are among the most recognized American artworks.' },
  { id: 'art-64', category: 'art', difficulty: 'medium', question: 'What is the art of folding paper into decorative shapes called?', answer: 'Origami', options: ['Kirigami', 'Origami', 'Decoupage', 'Papier-mache'], explanation: 'Origami originated in Japan (the word combines "ori" meaning folding and "kami" meaning paper). Traditional origami uses a single square sheet of paper without cutting or gluing. The crane is perhaps the most well-known origami figure.' },
  { id: 'art-65', category: 'art', difficulty: 'medium', question: 'Who designed the Sagrada Familia basilica in Barcelona?', answer: 'Antoni Gaudi', options: ['Antoni Gaudi', 'Santiago Calatrava', 'Frank Lloyd Wright', 'Le Corbusier'], explanation: 'Construction on the Sagrada Familia began in 1882 under architect Francisco de Paula del Villar, and Antoni Gaudi took over the project in 1883, completely transforming its design. It remains under construction more than 140 years later. Gaudi\'s unique organic style drew from nature, and he devoted the last 12 years of his life entirely to the project.' },
  { id: 'art-66', category: 'art', difficulty: 'medium', question: 'What 20th-century artist is famous for dripping and splattering paint on canvases laid on the floor?', answer: 'Jackson Pollock', options: ['Willem de Kooning', 'Jackson Pollock', 'Mark Rothko', 'Franz Kline'], explanation: 'Jackson Pollock developed his "drip technique" in the late 1940s, pouring and flinging paint from cans onto large canvases on the floor. His action paintings helped establish Abstract Expressionism as the first major American art movement.' },
  { id: 'art-67', category: 'art', difficulty: 'medium', question: 'What painting by Jan van Eyck is considered a masterpiece of Early Netherlandish art and depicts a couple in a room?', answer: 'The Arnolfini Portrait', options: ['The Arnolfini Portrait', 'The Descent from the Cross', 'The Garden of Earthly Delights', 'The Ghent Altarpiece'], explanation: 'Van Eyck painted the Arnolfini Portrait in 1434, showing a wealthy couple in their home with rich symbolic details. The convex mirror in the background reflects two additional figures and is inscribed with "Jan van Eyck was here."' },
  { id: 'art-68', category: 'art', difficulty: 'medium', question: 'What is gouache?', answer: 'An opaque watercolor paint', options: ['A type of oil paint', 'An opaque watercolor paint', 'A spray paint medium', 'A glossy acrylic finish'], explanation: 'Gouache is similar to watercolor but contains white pigment or chalk to make it opaque rather than transparent. It has been used for centuries in illustration, design, and fine art, and dries to a matte, velvety finish.' },
  { id: 'art-69', category: 'art', difficulty: 'medium', question: 'What Baroque painter was known for dramatic lighting and was convicted of murder?', answer: 'Caravaggio', options: ['Artemisia Gentileschi', 'Caravaggio', 'Peter Paul Rubens', 'Diego Velazquez'], explanation: 'Caravaggio (1571-1610) killed a man in a brawl in 1606 and spent the rest of his life fleeing justice. Despite his volatile life, he revolutionized painting with his dramatic chiaroscuro technique called "tenebrism."' },
  { id: 'art-70', category: 'art', difficulty: 'medium', question: 'What is the Venus de Milo missing?', answer: 'Both arms', options: ['Her head', 'Both arms', 'One leg', 'Her nose'], explanation: 'The Venus de Milo was discovered on the Greek island of Milos in 1820 and is believed to depict Aphrodite. The marble statue dates to around 130-100 BC and now stands in the Louvre. Her arms were already missing when she was found.' },
  { id: 'art-71', category: 'art', difficulty: 'medium', question: 'What art movement emerged in New York in the 1940s and 1950s, featuring large abstract canvases?', answer: 'Abstract Expressionism', options: ['Abstract Expressionism', 'Minimalism', 'Color Field Painting', 'Neo-Expressionism'], explanation: 'Abstract Expressionism was the first major American art movement and shifted the art world\'s center from Paris to New York. Key artists include Jackson Pollock, Mark Rothko, and Willem de Kooning.' },
  { id: 'art-72', category: 'art', difficulty: 'medium', question: 'Who painted "The Persistence of Memory" with melting clocks?', answer: 'Salvador Dali', options: ['Rene Magritte', 'Salvador Dali', 'Max Ernst', 'Giorgio de Chirico'], explanation: 'Dali painted The Persistence of Memory in 1931 in about five hours. The melting watches symbolize the irrelevance of time in the dream state. Dali said the idea came from watching Camembert cheese melting in the sun.' },
  { id: 'art-73', category: 'art', difficulty: 'medium', question: 'What ancient art technique involves hammering metal from the reverse side to create designs?', answer: 'Repousse', options: ['Intaglio', 'Repousse', 'Cloisonne', 'Filigree'], explanation: 'Repousse (French for "pushed back") involves shaping malleable metal from the reverse side to create a design in low relief. The technique has been used since antiquity, and the Statue of Liberty\'s copper skin was shaped using repousse.' },
  { id: 'art-74', category: 'art', difficulty: 'medium', question: 'What is the name of the artistic style characterized by ornate decoration popular in 17th-18th century Europe?', answer: 'Baroque', options: ['Rococo', 'Baroque', 'Mannerism', 'Neoclassicism'], explanation: 'Baroque art (roughly 1600-1750) featured dramatic movement, rich color, and grandeur, often used by the Catholic Church to inspire awe. Major Baroque artists include Caravaggio, Bernini, Rubens, and Rembrandt.' },
  { id: 'art-75', category: 'art', difficulty: 'medium', question: 'What photographer is known for black-and-white landscapes of the American West, especially Yosemite?', answer: 'Ansel Adams', options: ['Ansel Adams', 'Edward Weston', 'Dorothea Lange', 'Alfred Stieglitz'], explanation: 'Ansel Adams (1902-1984) developed the "Zone System" for precise exposure control in photography. His dramatic images of Yosemite and other national parks helped build public support for wilderness conservation.' },
  { id: 'art-76', category: 'art', difficulty: 'medium', question: 'What type of artwork is made by assembling different materials like newspaper, fabric, and photos onto a surface?', answer: 'Collage', options: ['Montage', 'Collage', 'Assemblage', 'Decoupage'], explanation: 'Collage comes from the French word "coller" meaning "to glue." Picasso and Braque pioneered collage as fine art in 1912, pasting paper, fabric, and other materials onto their Cubist paintings.' },
  { id: 'art-77', category: 'art', difficulty: 'medium', question: 'Who painted "Whistler\'s Mother"?', answer: 'James McNeill Whistler', options: ['John Singer Sargent', 'James McNeill Whistler', 'Winslow Homer', 'Thomas Eakins'], explanation: 'The painting\'s actual title is "Arrangement in Grey and Black No. 1" (1871). Whistler\'s mother, Anna McNeill Whistler, agreed to model when the original model failed to show up. It hangs in the Musee d\'Orsay in Paris.' },
  { id: 'art-78', category: 'art', difficulty: 'medium', question: 'What ancient Greek architectural order features scrolled capitals on its columns?', answer: 'Ionic', options: ['Doric', 'Ionic', 'Corinthian', 'Tuscan'], explanation: 'The Ionic order is characterized by its volute (scroll-shaped) capitals and is more slender and ornamental than the Doric order. The Erechtheion on the Acropolis in Athens is a famous example of Ionic architecture.' },
  { id: 'art-79', category: 'art', difficulty: 'medium', question: 'What was the first major art heist of the 20th century, occurring at the Isabella Stewart Gardner Museum in 1990?', answer: '13 works including Vermeer\'s "The Concert"', options: ['The Mona Lisa', '13 works including Vermeer\'s "The Concert"', 'Rembrandt\'s "Night Watch"', 'A single Monet painting'], explanation: 'On March 18, 1990, two men disguised as police officers stole 13 works worth an estimated $500 million from the Gardner Museum in Boston. The crime remains unsolved, and the empty frames still hang on the walls as placeholders.' },
  { id: 'art-80', category: 'art', difficulty: 'medium', question: 'What Mexican muralist was married to Frida Kahlo?', answer: 'Diego Rivera', options: ['David Alfaro Siqueiros', 'Diego Rivera', 'Jose Clemente Orozco', 'Rufino Tamayo'], explanation: 'Diego Rivera was one of Mexico\'s most prominent muralists, known for large-scale public works depicting Mexican history and society. He and Kahlo had a famously turbulent relationship — they married, divorced, and remarried.' },
  { id: 'art-81', category: 'art', difficulty: 'medium', question: 'What is the art of creating designs in colored glass, typically found in churches?', answer: 'Stained glass', options: ['Blown glass', 'Stained glass', 'Leaded glass', 'Fused glass'], explanation: 'Stained glass reached its peak in European Gothic cathedrals of the 12th and 13th centuries. The windows at Chartres Cathedral in France are among the finest surviving examples, using cobalt blue glass that has become world-famous.' },
  { id: 'art-82', category: 'art', difficulty: 'medium', question: 'What Roy Lichtenstein painting features a crying woman in comic-book style?', answer: 'Drowning Girl', options: ['Whaam!', 'Drowning Girl', 'Hopeless', 'Oh, Jeff'], explanation: 'Lichtenstein\'s Drowning Girl (1963) was based on a panel from a DC Comics story. His Pop Art style used Ben-Day dots (the tiny circles used in commercial printing) and bold outlines to recreate comic book imagery at a large scale.' },
  { id: 'art-83', category: 'art', difficulty: 'medium', question: 'What is the Japanese art of repairing broken pottery with gold?', answer: 'Kintsugi', options: ['Raku', 'Kintsugi', 'Wabi-sabi', 'Ikebana'], explanation: 'Kintsugi (meaning "golden joinery") treats breakage as part of an object\'s history rather than something to disguise. The technique uses lacquer mixed with gold, silver, or platinum powder, making the repair a visible and beautiful feature.' },
  { id: 'art-84', category: 'art', difficulty: 'medium', question: 'What painting by Rene Magritte shows a pipe with the text "This is not a pipe"?', answer: 'The Treachery of Images', options: ['The Son of Man', 'The Treachery of Images', 'The Human Condition', 'Golconda'], explanation: 'Magritte painted The Treachery of Images in 1929, with the text "Ceci n\'est pas une pipe." His point was that the painting is not actually a pipe — it is a representation of one. The work challenges viewers\' assumptions about the relationship between objects and their depictions.' },
  { id: 'art-85', category: 'art', difficulty: 'medium', question: 'What is a triptych?', answer: 'A three-paneled artwork', options: ['A three-color printing technique', 'A three-paneled artwork', 'A triangular sculpture', 'A three-layered painting'], explanation: 'Triptychs originated in early Christian art as portable altarpieces with side panels that could fold over the center panel. Hieronymus Bosch\'s "The Garden of Earthly Delights" (c. 1500) is one of the most famous triptychs in art history.' },
  { id: 'art-86', category: 'art', difficulty: 'medium', question: 'What style of architecture features pointed arches, flying buttresses, and ribbed vaults?', answer: 'Gothic', options: ['Romanesque', 'Gothic', 'Baroque', 'Byzantine'], explanation: 'Gothic architecture dominated Europe from the mid-12th to 16th centuries. The style\'s engineering innovations allowed walls to be thinner and filled with large stained glass windows. Notre-Dame de Paris and Chartres Cathedral are iconic examples.' },
  { id: 'art-87', category: 'art', difficulty: 'medium', question: 'Who created "Bird in Space," a series of abstract bronze sculptures?', answer: 'Constantin Brancusi', options: ['Alberto Giacometti', 'Constantin Brancusi', 'Henry Moore', 'Alexander Calder'], explanation: 'Brancusi created multiple versions of Bird in Space between 1923 and 1940, reducing the bird form to a sleek, elongated shape. When one was imported to the U.S. in 1926, customs officials classified it as a manufactured object rather than art and tried to charge a tariff.' },
  { id: 'art-88', category: 'art', difficulty: 'medium', question: 'What decorative art movement of the 1920s and 1930s featured bold geometric designs and lavish ornamentation?', answer: 'Art Deco', options: ['Art Nouveau', 'Art Deco', 'Bauhaus', 'Streamline Moderne'], explanation: 'Art Deco took its name from the 1925 Exposition Internationale des Arts Decoratifs in Paris. The style influenced everything from architecture (the Chrysler Building) to fashion, furniture, and jewelry, combining modernist styles with fine craftsmanship.' },
  { id: 'art-89', category: 'art', difficulty: 'medium', question: 'What is the term for a painting that depicts inanimate objects like fruit, flowers, or household items?', answer: 'Still life', options: ['Nature morte', 'Still life', 'Vanitas', 'Genre painting'], explanation: 'Still life painting became a distinct genre in the 16th and 17th centuries, particularly in the Netherlands. Dutch and Flemish painters elevated it to an art form, often including symbolic objects representing the passage of time (vanitas).' },
  { id: 'art-90', category: 'art', difficulty: 'medium', question: 'Who designed the Vietnam Veterans Memorial in Washington, D.C.?', answer: 'Maya Lin', options: ['Frank Gehry', 'Maya Lin', 'I.M. Pei', 'Daniel Libeskind'], explanation: 'Maya Lin was a 21-year-old Yale architecture student when her design was selected from 1,421 entries in 1981. The memorial\'s two black granite walls inscribed with the names of over 58,000 fallen service members form a V-shape cut into the earth.' },
  { id: 'art-91', category: 'art', difficulty: 'hard', question: 'What painting technique involves applying thin, transparent layers of paint over a dried layer?', answer: 'Glazing', options: ['Scumbling', 'Glazing', 'Wet-on-wet', 'Underpainting'], explanation: 'Glazing creates luminous, jewel-like effects by layering transparent paint over opaque layers. Old Masters like Jan van Eyck and Vermeer perfected the technique with oil paints, building up many thin layers to achieve rich, glowing colors.' },
  { id: 'art-92', category: 'art', difficulty: 'hard', question: 'What Renaissance artist painted "The School of Athens"?', answer: 'Raphael', options: ['Leonardo da Vinci', 'Michelangelo', 'Raphael', 'Titian'], explanation: 'Raphael painted The School of Athens between 1509 and 1511 as part of a commission to decorate rooms in the Vatican Palace. The fresco depicts famous ancient Greek philosophers, with Plato and Aristotle at the center, and includes portraits of contemporary artists like Leonardo and Michelangelo.' },
  { id: 'art-93', category: 'art', difficulty: 'hard', question: 'What is the name of the ancient Greek sculpture that depicted the Trojan priest and his sons being attacked by serpents?', answer: 'Laocoon and His Sons', options: ['Dying Gaul', 'Laocoon and His Sons', 'Discobolus', 'Winged Victory'], explanation: 'Laocoon and His Sons was rediscovered in Rome in 1506 and had an enormous influence on Renaissance and Baroque art. The marble sculpture dates to approximately 40-30 BC and is now in the Vatican Museums.' },
  { id: 'art-94', category: 'art', difficulty: 'hard', question: 'What artist wrapped entire buildings and landscapes in fabric as public art installations?', answer: 'Christo', options: ['Christo', 'James Turrell', 'Robert Smithson', 'Olafur Eliasson'], explanation: 'Christo and his wife Jeanne-Claude created massive environmental artworks, including wrapping the Reichstag in Berlin (1995) and surrounding islands in Miami with pink fabric (1983). Their projects were always temporary and entirely self-financed through art sales.' },
  { id: 'art-95', category: 'art', difficulty: 'hard', question: 'What 1913 New York exhibition introduced Americans to avant-garde European art and caused a public scandal?', answer: 'The Armory Show', options: ['The Salon des Refuses', 'The Armory Show', 'Gallery 291', 'The Whitney Biennial'], explanation: 'The International Exhibition of Modern Art at the 69th Regiment Armory showcased about 1,300 works. Marcel Duchamp\'s "Nude Descending a Staircase, No. 2" was the most controversial piece. The show permanently changed American art by introducing Cubism, Fauvism, and other European movements.' },
  { id: 'art-96', category: 'art', difficulty: 'hard', question: 'What German art school, founded in 1919, merged fine arts with crafts and design?', answer: 'Bauhaus', options: ['De Stijl', 'Bauhaus', 'Vienna Secession', 'Arts and Crafts Movement'], explanation: 'The Bauhaus was founded by Walter Gropius in Weimar, Germany and operated until 1933 when the Nazis forced it to close. Its philosophy of unifying art, craft, and technology profoundly influenced modern architecture, design, and art education worldwide.' },
  { id: 'art-97', category: 'art', difficulty: 'hard', question: 'What painting by Hieronymus Bosch depicts paradise, earthly pleasures, and hell across three panels?', answer: 'The Garden of Earthly Delights', options: ['The Last Judgment', 'The Garden of Earthly Delights', 'The Haywain Triptych', 'The Temptation of St. Anthony'], explanation: 'Bosch painted The Garden of Earthly Delights around 1490-1510, and its bizarre imagery continues to puzzle art historians. The triptych is housed in the Prado Museum in Madrid and shows the creation of the world, human indulgence, and the consequences of sin.' },
  { id: 'art-98', category: 'art', difficulty: 'hard', question: 'What artist is known for readymades, including submitting a urinal titled "Fountain" as art?', answer: 'Marcel Duchamp', options: ['Man Ray', 'Marcel Duchamp', 'Francis Picabia', 'Kurt Schwitters'], explanation: 'Duchamp submitted "Fountain" — a store-bought urinal signed "R. Mutt" — to a 1917 exhibition, challenging the very definition of art. His concept of the "readymade" (ordinary objects presented as art) profoundly influenced Conceptual art and remains debated today.' },
  { id: 'art-99', category: 'art', difficulty: 'hard', question: 'What ancient painting technique uses heated beeswax mixed with colored pigments?', answer: 'Encaustic', options: ['Tempera', 'Encaustic', 'Fresco secco', 'Casein'], explanation: 'Encaustic painting dates back to ancient Greece and was used extensively in Roman Egypt for the famous Fayum mummy portraits. The word comes from the Greek "enkaustikos" meaning "to burn in," as heat is used to fuse the wax medium.' },
  { id: 'art-100', category: 'art', difficulty: 'hard', question: 'What Post-Impressionist painted "Where Do We Come From? What Are We? Where Are We Going?"', answer: 'Paul Gauguin', options: ['Paul Cezanne', 'Paul Gauguin', 'Henri de Toulouse-Lautrec', 'Georges Seurat'], explanation: 'Gauguin painted this monumental work (nearly 4.6 meters wide) in Tahiti in 1897 during a period of despair. He intended it as his artistic testament, reading right to left as an allegory of human life from birth to death.' },
  { id: 'art-101', category: 'art', difficulty: 'hard', question: 'What Italian Baroque artist was one of the few female painters to gain international recognition in her era?', answer: 'Artemisia Gentileschi', options: ['Sofonisba Anguissola', 'Artemisia Gentileschi', 'Lavinia Fontana', 'Elisabetta Sirani'], explanation: 'Artemisia Gentileschi (1593-1656) is known for powerful depictions of biblical heroines, especially "Judith Slaying Holofernes." She was the first woman admitted to the Accademia di Arte del Disegno in Florence and overcame a traumatic assault to achieve artistic fame.' },
  { id: 'art-102', category: 'art', difficulty: 'hard', question: 'What massive earthwork sculpture in Utah\'s Great Salt Lake was created by Robert Smithson in 1970?', answer: 'Spiral Jetty', options: ['Lightning Field', 'Spiral Jetty', 'Double Negative', 'Sun Tunnels'], explanation: 'Spiral Jetty is a 1,500-foot-long coil of black basalt rock, earth, and salt crystals extending into the Great Salt Lake. Smithson chose the site partly because of the lake\'s red coloring from microorganisms. The work periodically disappears and reappears depending on water levels.' },
  { id: 'art-103', category: 'art', difficulty: 'hard', question: 'What technique did Georges Seurat develop that uses tiny distinct dots of pure color?', answer: 'Pointillism', options: ['Divisionism', 'Pointillism', 'Stippling', 'Neo-Impressionism'], explanation: 'While Seurat called his technique "Chromoluminarism" or "Divisionism," critics coined the term "Pointillism." The technique is based on color theory — when viewed from a distance, the tiny dots of pure color optically blend in the viewer\'s eye to create fuller tones.' },
  { id: 'art-104', category: 'art', difficulty: 'hard', question: 'What Spanish architect designed the Casa Mila and Park Guell in Barcelona?', answer: 'Antoni Gaudi', options: ['Santiago Calatrava', 'Antoni Gaudi', 'Rafael Moneo', 'Ricardo Bofill'], explanation: 'Gaudi\'s Casa Mila (La Pedrera, completed 1912) has an undulating stone facade with no straight lines. His organic architectural style drew from nature, and seven of his works in Barcelona are UNESCO World Heritage Sites.' },
  { id: 'art-105', category: 'art', difficulty: 'hard', question: 'What art movement, led by Kazimir Malevich, reduced art to pure geometric abstraction?', answer: 'Suprematism', options: ['Constructivism', 'Suprematism', 'De Stijl', 'Minimalism'], explanation: 'Malevich founded Suprematism around 1915 with works like "Black Square" — a simple black square on a white background. He declared it "the supremacy of pure artistic feeling" over the depiction of objects, radically breaking from representational art.' },
  { id: 'art-106', category: 'art', difficulty: 'hard', question: 'What American artist created large-scale steel sculptures including "Cubi" series?', answer: 'David Smith', options: ['Richard Serra', 'David Smith', 'Alexander Calder', 'Donald Judd'], explanation: 'David Smith (1906-1965) was a pioneer of welded metal sculpture in the United States. His Cubi series, created in the last years of his life, features geometric stainless steel forms balanced in dynamic compositions.' },
  { id: 'art-107', category: 'art', difficulty: 'hard', question: 'What painting by Diego Velazquez shows the artist painting the Spanish royal family while looking at the viewer?', answer: 'Las Meninas', options: ['The Surrender of Breda', 'Las Meninas', 'The Spinners', 'Portrait of Pope Innocent X'], explanation: 'Las Meninas (1656) is considered Velazquez\'s masterpiece and one of the most analyzed paintings in Western art history. The complex composition plays with perspective — the king and queen are reflected in a mirror, suggesting the viewer stands where they stood.' },
  { id: 'art-108', category: 'art', difficulty: 'hard', question: 'What is sfumato, a technique perfected by Leonardo da Vinci?', answer: 'Soft, gradual blending of tones without visible lines', options: ['Using gold leaf as background', 'Soft, gradual blending of tones without visible lines', 'Painting with fingers instead of brushes', 'Creating texture with thick paint application'], explanation: 'Sfumato comes from the Italian "sfumare" meaning "to evaporate like smoke." Leonardo used it extensively in the Mona Lisa, creating imperceptible transitions between colors and tones. The technique gives the painting its mysterious, atmospheric quality.' },
  { id: 'art-109', category: 'art', difficulty: 'hard', question: 'What is one of the oldest known examples of figurative cave art, found in Indonesia?', answer: 'A pig painting in Sulawesi, dated to at least 45,500 years ago', options: ['Lascaux cave paintings in France', 'Altamira bison paintings in Spain', 'A pig painting in Sulawesi, dated to at least 45,500 years ago', 'Chauvet cave paintings in France'], explanation: 'A life-sized painting of a warty pig in the Leang Tedongnge cave on the island of Sulawesi, Indonesia was discovered in 2017 and dated to at least 45,500 years ago (published in 2021). Even older cave art has since been found at nearby sites, pushing dates back to over 51,000 years ago.' },
  { id: 'art-110', category: 'art', difficulty: 'hard', question: 'What Dutch graphic artist is known for mathematically inspired impossible constructions and tessellations?', answer: 'M.C. Escher', options: ['Piet Mondrian', 'M.C. Escher', 'Theo van Doesburg', 'Karel Appel'], explanation: 'M.C. Escher (1898-1972) created lithographs and woodcuts featuring impossible architecture, infinite staircases, and interlocking patterns. Despite having no formal mathematical training, his work has been deeply studied by mathematicians.' },
  { id: 'art-111', category: 'art', difficulty: 'hard', question: 'What Neo-Expressionist artist rose from the New York graffiti scene and frequently collaborated with Andy Warhol?', answer: 'Jean-Michel Basquiat', options: ['Keith Haring', 'Jean-Michel Basquiat', 'Kenny Scharf', 'Julian Schnabel'], explanation: 'Basquiat (1960-1988) began as a graffiti artist under the tag "SAMO" before becoming one of the most celebrated artists of the 1980s. His raw, text-heavy paintings explored themes of race, class, and identity. His "Untitled" (1982) skull painting sold for $110.5 million in 2017.' },
  { id: 'art-112', category: 'art', difficulty: 'hard', question: 'What is the name for the golden ratio often found in art and architecture, approximately 1.618?', answer: 'Phi', options: ['Pi', 'Phi', 'Theta', 'Omega'], explanation: 'The golden ratio (phi, approximately 1.618) appears throughout art, architecture, and nature. Artists from Leonardo da Vinci to Salvador Dali have used it to create pleasing compositions. The Parthenon\'s facade and the spiral of a nautilus shell both approximate this ratio.' },
  { id: 'art-113', category: 'art', difficulty: 'hard', question: 'What American architect designed Fallingwater, a house built over a waterfall?', answer: 'Frank Lloyd Wright', options: ['Louis Sullivan', 'Frank Lloyd Wright', 'Philip Johnson', 'Mies van der Rohe'], explanation: 'Wright designed Fallingwater in 1935 for the Kaufmann family in rural Pennsylvania. The cantilevered design integrates the house with the surrounding forest and waterfall, and it is now a UNESCO World Heritage Site visited by over 160,000 people annually.' },
  { id: 'art-114', category: 'art', difficulty: 'hard', question: 'What artist created "The Physical Impossibility of Death in the Mind of Someone Living," a shark preserved in formaldehyde?', answer: 'Damien Hirst', options: ['Jeff Koons', 'Damien Hirst', 'Tracey Emin', 'Anish Kapoor'], explanation: 'Hirst created this work in 1991, commissioning a 14-foot tiger shark to be suspended in a glass tank of formaldehyde. It became a defining work of the Young British Artists (YBAs) movement and was reportedly purchased by hedge fund manager Steven A. Cohen for a reported $8 million.' },
  { id: 'art-115', category: 'art', difficulty: 'hard', question: 'What ancient Roman technique used small cubes of stone or glass to create elaborate floor designs?', answer: 'Opus tessellatum', options: ['Opus sectile', 'Opus tessellatum', 'Opus vermiculatum', 'Opus signinum'], explanation: 'Opus tessellatum used standardized small cubes (tesserae) typically 1-2 cm in size to create large-scale mosaic designs. It was the most common mosaic technique in the Roman Empire, used for both geometric patterns and figurative scenes in villas and public buildings.' },
  { id: 'art-116', category: 'art', difficulty: 'hard', question: 'What Pre-Raphaelite painting by John Everett Millais depicts a character from Hamlet floating in a river?', answer: 'Ophelia', options: ['The Lady of Shalott', 'Ophelia', 'Proserpine', 'Beata Beatrix'], explanation: 'Millais painted Ophelia in 1851-52, showing Shakespeare\'s character drowning while singing. The model, Elizabeth Siddal, posed in a bathtub of water and reportedly caught a severe cold. The painting\'s detailed botanical accuracy has been praised by botanists.' },
  { id: 'art-117', category: 'art', difficulty: 'hard', question: 'What contemporary artist is known for balloon dog sculptures and sold "Rabbit" for $91.1 million in 2019?', answer: 'Jeff Koons', options: ['Takashi Murakami', 'Jeff Koons', 'Damien Hirst', 'Maurizio Cattelan'], explanation: 'Jeff Koons\'s stainless steel "Rabbit" (1986) sold at Christie\'s in 2019 for $91.1 million, at that time a record for a living artist. His balloon dog sculptures, made of mirror-polished stainless steel, have become some of the most recognizable works of contemporary art.' },
  { id: 'art-118', category: 'art', difficulty: 'hard', question: 'What post-war art movement used stripes, chevrons, and geometric patterns to create optical illusions?', answer: 'Op Art', options: ['Hard-edge painting', 'Op Art', 'Kinetic Art', 'Geometric Abstraction'], explanation: 'Op Art (Optical Art) emerged in the 1960s, with Bridget Riley and Victor Vasarely as its leading practitioners. Riley\'s black-and-white paintings create powerful sensations of movement and vibration through precisely arranged geometric forms.' },
  { id: 'art-119', category: 'art', difficulty: 'hard', question: 'What term describes the atmospheric perspective technique that makes distant objects appear bluer and hazier?', answer: 'Aerial perspective', options: ['Linear perspective', 'Aerial perspective', 'Foreshortening', 'Vanishing point'], explanation: 'Aerial (or atmospheric) perspective mimics how the atmosphere affects the appearance of distant objects. Leonardo da Vinci was among the first to systematically describe the technique, noting that distant mountains appear bluer because of particles in the air scattering light.' },
  { id: 'art-120', category: 'art', difficulty: 'hard', question: 'What Austrian artist founded the Vienna Secession movement and painted "The Kiss"?', answer: 'Gustav Klimt', options: ['Egon Schiele', 'Gustav Klimt', 'Oskar Kokoschka', 'Koloman Moser'], explanation: 'Klimt (1862-1918) co-founded the Vienna Secession in 1897 as a break from conservative Austrian art. "The Kiss" (1907-08) features his signature gold leaf technique and is housed in the Belvedere Museum in Vienna. His portrait of Adele Bloch-Bauer I sold for $135 million in 2006.' },
  { id: 'art-121', category: 'art', difficulty: 'hard', question: 'What is the name of the technique where a sculptor carves a figure that appears to emerge from unfinished stone?', answer: 'Non finito', options: ['Alto-rilievo', 'Non finito', 'Contrapposto', 'Pietra dura'], explanation: 'Non finito (Italian for "not finished") was used deliberately by Michelangelo in works like his "Slaves" series, where figures appear to struggle free from the raw marble. Whether these works were intentionally left unfinished or simply abandoned remains debated by scholars.' },
  { id: 'art-122', category: 'art', difficulty: 'hard', question: 'What artist created mobile sculptures — hanging kinetic works that move with air currents?', answer: 'Alexander Calder', options: ['Alexander Calder', 'Naum Gabo', 'Jean Tinguely', 'George Rickey'], explanation: 'Alexander Calder invented the mobile in the early 1930s, with Marcel Duchamp coining the term. His delicately balanced hanging sculptures introduced real movement into art, and his monumental stabiles (static sculptures) stand in public spaces worldwide.' },
  { id: 'art-123', category: 'art', difficulty: 'hard', question: 'What controversial 1999 exhibition at the Brooklyn Museum featured works by Young British Artists and sparked public outrage?', answer: 'Sensation', options: ['Sensation', 'Freeze', 'Saatchi Collection', 'Apocalypse'], explanation: 'The "Sensation" exhibition included Chris Ofili\'s "The Holy Virgin Mary" (which incorporated elephant dung) and provoked New York Mayor Rudy Giuliani to threaten to cut the museum\'s funding. The controversy drew massive attendance and intensified debates about censorship and public art funding.' },
  { id: 'art-124', category: 'art', difficulty: 'hard', question: 'What Japanese art movement of the 1950s-60s, meaning "concrete," bridged Eastern and Western avant-garde?', answer: 'Gutai', options: ['Mono-ha', 'Gutai', 'Superflat', 'Mingei'], explanation: 'The Gutai Art Association was founded by Jiro Yoshihara in 1954 in Osaka. Members created radical performative works — Kazuo Shiraga painted with his feet while suspended from a rope, and Saburo Murakami threw himself through paper screens. The group anticipated Happenings and Performance Art.' },
  { id: 'art-125', category: 'art', difficulty: 'hard', question: 'What Post-Impressionist artist is considered the "father of modern art" for bridging Impressionism and Cubism?', answer: 'Paul Cezanne', options: ['Paul Gauguin', 'Paul Cezanne', 'Vincent van Gogh', 'Henri de Toulouse-Lautrec'], explanation: 'Cezanne\'s revolutionary approach to form and color — breaking natural forms into geometric shapes and using patches of color to build structure — directly influenced Picasso and Braque\'s development of Cubism. Both Matisse and Picasso called him "the father of us all."' },
]
